/** Modulo generato dal layer in fase di build (nuxt.config.ts): pagine e route del progetto. */
declare module '#nuxt-shield/app-routes' {
  /** Primo segmento statico di ogni pagina (es. "blog" per /blog/:slug). */
  export const pageSegments: string[]
  /** Route del server senza parametri (es. /sitemap.xml). */
  export const exactRoutes: string[]
  /** Parte fissa delle route del server con parametri (es. /blog-media/ per /blog-media/**). */
  export const routePrefixes: string[]
}
